def find_uniform_rectangles(grid, min_rows=3, min_cols=3):
    """Find rectangular regions of uniform value with at least min_rows x min_cols cells"""
    rectangles = []
    seen = set()

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if (r, c) in seen:
                continue

            # Find all larger rectangles starting at (r, c)
            for hr in range(min_rows, len(grid) - r + 1):
                for wc in range(min_cols, len(grid[0]) - c + 1):
                    # Check if this rectangle is uniform
                    uniform = True
                    for dr in range(hr):
                        for dc in range(wc):
                            if grid[r + dr][c + dc] != grid[r][c]:
                                uniform = False
                                break
                        if not uniform:
                            break

                    if uniform:
                        rect = (r, c, r + hr - 1, c + wc - 1)
                        rectangles.append(rect)
                        seen.add((r, c))
                        break  # Found one starting here, move on
        seen.add((r, c))

    # Merge overlapping rectangles (keep largest)
    merged = []
    for rect in rectangles:
        r1, c1, r2, c2 = rect
        area = (r2 - r1 + 1) * (c2 - c1 + 1)
        merged.append((rect, area))

    # Sort by area and keep largest non-overlapping
    merged.sort(key=lambda x: -x[1])

    result = []
    used = set()
    for rect, area in merged:
        r1, c1, r2, c2 = rect
        rect_set = {(r, c) for r in range(r1, r2 + 1) for c in range(c1, c2 + 1)}
        if rect_set.isdisjoint(used):
            result.append(rect)
            used.update(rect_set)

    return result

