def find_regions_to_transform(grid):
    """Find maximal uniform rectangles with size >= 9 (3x3 minimum)"""
    rows, cols = len(grid), len(grid[0])
    regions = []
    visited = set()

    for r in range(rows):
        for c in range(cols):
            if (r, c) in visited:
                continue

            val = grid[r][c]

            # Expand right
            max_c = c
            for c_test in range(c + 1, cols):
                if grid[r][c_test] == val:
                    max_c = c_test
                else:
                    break

            if max_c == c:
                visited.add((r, c))
                continue

            # Expand down
            max_r = r
            for r_test in range(r + 1, rows):
                all_match = all(grid[r_test][cc] == val for cc in range(c, max_c + 1))
                if all_match:
                    max_r = r_test
                else:
                    break

            rect = (r, c, max_r, max_c)
            visited.update((rr, cc) for rr in range(r, max_r + 1) for cc in range(c, max_c + 1))

            size = (max_r - r + 1) * (max_c - c + 1)
            if size >= 9:  # 3x3 minimum
                regions.append(rect)

    return regions

def transform_grid(grid, regions):
    """Apply the transform: replace each region with 4s"""
    result = [row[:] for row in grid]

    for (r1, c1, r2, c2) in regions:
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                result[r][c] = 4

    return result

