def find_maximal_uniform_rectangles_with_size_threshold(grid, min_size=9):
    """Find all maximal uniform rectangles with size >= min_size"""
    rows, cols = len(grid), len(grid[0])
    rectangles = []

    for r_start in range(rows):
        for c_start in range(cols):
            if (r_start, c_start) in [rect[:2] for rect in rectangles]:
                continue

            val = grid[r_start][c_start]
            original_count = len(rectangles)
            for r_end in range(r_start, rows):
                for c_end in range(c_start, cols):
                    # Check if rectangle (r_start, c_start, r_end, c_end) is uniform
                    uniform = all(grid[rr][cc] == val for rr in range(r_start, r_end + 1) for cc in range(c_start, c_end + 1))
                    if uniform and (r_end - r_start + 1) * (c_end - c_start + 1) >= min_size:
                        rectangles.append((r_start, c_start, r_end, c_end))

    # Now filter to keep only maximal rectangles (not contained in larger ones)
    # Sort by size descending
    rectangles = sorted(rectangles, key=lambda r: (r[2]-r[0]+1)*(r[3]-r[1]+1), reverse=True)
    max_rectangles = []
    for rect in rectangles:
        r1, c1, r2, c2 = rect
        contained = False
        for existing in max_rectangles:
            er1, ec1, er2, ec2 = existing
            if r1 >= er1 and c1 >= ec1 and r2 <= er2 and c2 <= ec2:
                contained = True
                break
        if not contained:
            max_rectangles.append(rect)

    return max_rectangles

